/* one adjustable ini knob shown as a slider row in the module card */
typedef struct {
    const char    *key;      /* key inside modules\<id>.ini              */
    const wchar_t *label;    /* right-aligned caption                    */
    float          minV, maxV, defV;   /* in DISPLAY units               */
    BOOL           isInt;    /* display value is an integer             */
    const wchar_t *unit;     /* appended to the value ("µm", "mm", "×")  */
    float          iniMul;   /* ini value = display * iniMul (µm <- mm)  */
    float          step;     /* display quantization (0 = 0.1)           */
    BOOL           noDefHint;/* do not show "(default X)" next to values */
} SliderDef;

/* one-click bundle of ini values shown as a pill button; the whole
 * "quality" tuning is three coupled numbers, so they change together */
typedef struct {
    const wchar_t *label;     /* "Fine"                                  */
    const wchar_t *spreadText;/* "0.05 mm" (display only)                */
    int            spreadUm;  /* green_spread_um                         */
    int            frames;    /* green_frames                            */
    int            supported; /* green_supported                         */
} PresetDef;

typedef struct {
    const char    *id;        /* section in modules.ini, name under modules\ */
    const wchar_t *title;     /* UI name                                   */
    const char    *version;
    const wchar_t *desc;      /* UI description (one line)                 */
    const wchar_t *resDll;    /* RCDATA name of the module binary          */
    const wchar_t *resIni;    /* RCDATA name of the module config template */
    const SliderDef *sliders; /* adjustable ini knobs (slider rows)        */
    int             nSliders;
    const PresetDef *presets; /* one-click value bundles (pill buttons)    */
    int             nPresets;
    const wchar_t  *presetCap;/* caption above the preset row              */
    BOOL           needsSiblings; /* module also runs in sibling processes
                                   * (scanservice.exe): keep the [host]
                                   * sibling_* whitelist in sync          */
    BOOL           hasFileBtn;  /* card shows "Choose file…" / "Reset":
                                 * the module reads a user image from
                                 * modules\ (see the wallpaper module)   */
} ModDef;

